import React, { useContext, useEffect, useRef, useState } from "react";
import { useTheme } from "../../../../themes/ThemeProvider";
import { IconGroup } from "../utilities/popovers";
import {
  ChangerGroup,
  CHANGER_TYPE,
} from "../utilities/valueChangers";
import { checkMouseInRadius, drawCircleAt, getMiddleOfRectangle, getRandomColour, inRect, padRect } from "../utilities/usefulFunctions";
import { MobileContext } from "../../../../contexts/MobileContext";
import {
  useCanvasScene,
  SceneCanvas,
  createPointerTracker,
  clearCanvas,
} from "../utilities/engine";

export default function Pinball({ visibleUI }) {
  const { theme } = useTheme();
  const mousePosRef = useRef({ x: 0, y: 0 });
  const mouseClickRef = useRef(false);
  const touchActiveRef = useRef(false);

  const bouncynessRef = useRef(100);

  const gridSpacingX = useRef(200);
  const gridSpacingY = useRef(200);
  const ballRef = useRef(null);
  const controllables = useRef([]);
  const simulationSpeedRef = useRef(100);
  const visibleUIRef = useRef(visibleUI);
  const [, setRender] = useState(0); // Dummy state to force re-render

  const mobile = useContext(MobileContext)

  const canvasRef = useCanvasScene(({ canvas, ctx, onCleanup }) => {
    const gravity = 0.02;
    const maxFallSpeed = 13;

    onCleanup(
      createPointerTracker(canvas, {
        posRef: mousePosRef,
        downRef: mouseClickRef,
        touchActiveRef,
      })
    );

    const BALL_MAX_VX = 15.0
    const BALL_MAX_VY = 15.0

    class Ball {
      constructor(x, y, vx, vy) {
        this.x = x;
        this.y = y;
        this.vx = vx;
        this.vy = vy;
        this.size = mobile ? 10 : 20;
        this.color = theme.secondary;
        this.canBeHit = true;
        this.stuckCounter = 0;
        this.lastX = x;
        this.lastY = y;
        this.stuckThreshold = 30; // frames to detect if stuck
      }

      update() {
        if (this.vy < maxFallSpeed) {
          this.vy += gravity;
        }

        if (Math.abs(this.vx) > BALL_MAX_VX) {
          this.vx = Math.sign(this.vx) * BALL_MAX_VX;
        }

        if (Math.abs(this.vy) > BALL_MAX_VY) {
          this.vy = Math.sign(this.vy) * BALL_MAX_VY;
        }

        // check if ball is stuck 
        const distanceMoved = Math.sqrt((this.x - this.lastX) ** 2 + (this.y - this.lastY) ** 2);
        if (distanceMoved < 1 && Math.abs(this.vx) < 0.5 && Math.abs(this.vy) < 0.5) {
          this.stuckCounter++;
          if (this.stuckCounter > this.stuckThreshold) {
            // ball is stuck, give it a push
            console.log("Ball stuck, applying emergency push");
            this.vy = -3; // Push upward
            this.vx += (Math.random() - 0.5) * 2; // random horizontal push
            this.stuckCounter = 0;
          }
        } else {
          this.stuckCounter = 0;
        }

        // add minimum velocity threshold to prevent getting stuck
        const MIN_VELOCITY = 0.5;
        if (Math.abs(this.vx) < MIN_VELOCITY && Math.abs(this.vy) < MIN_VELOCITY) {
          // give it a small push downward if nearly stationary
          if (Math.abs(this.vy) < 0.1) {
            this.vy = MIN_VELOCITY;
          }
          // add slight horizontal randomness to break symmetrical situations
          this.vx += (Math.random() - 0.5) * 0.2;
        }

        // store previous position for stuck detection
        this.lastX = this.x;
        this.lastY = this.y;

        // prevent tunneling
        const new_potential_pos = this.ray_cast_collisions();

        if (!new_potential_pos) {
          this.x += (this.vx * simulationSpeedRef.current) / 100;
          this.y += (this.vy * simulationSpeedRef.current) / 100;
        } else {
          this.x = new_potential_pos.x;
          this.y = new_potential_pos.y;
          this.vx = new_potential_pos.vx;
          this.vy = new_potential_pos.vy;
        }

        if (this.y > canvas.height) {
          this.y = this.size * 2;
          this.x = Math.random() * canvas.width;
          this.vy = 0;
          this.vx = 0;
          this.stuckCounter = 0; // Reset stuck counter
        }

        if (this.y - this.size < 0.0) {
          this.vy *= -1;
        }

        if (this.x >= canvas.width - this.size) {
          this.vx *= -1;
        }

        if (this.x < 0 + this.size) {
          this.vx *= -1;
        }

      }

      draw() {
        drawCircleAt(ctx, this.x, this.y, this.size, this.color);
      }

      ray_cast_collisions() {
        const deltaX = (this.vx * simulationSpeedRef.current) / 100;
        const deltaY = (this.vy * simulationSpeedRef.current) / 100;

        const max_steps = 50;

        // Track previous step to calculate collision point more accurately
        let prev_x = this.x;
        let prev_y = this.y;

        for (let steps = 1; steps < max_steps; steps++) {
          const check_x = this.x + (deltaX / max_steps) * steps;
          const check_y = this.y + (deltaY / max_steps) * steps;

          // Check collisions with controllables (paddles)
          for (let i = 0; i < controllables.current.length; i++) {
            const pos = controllables.current[i].check_collision_with_pos(check_x, check_y);
            if (pos) {
              // For paddles, ensure ball is positioned safely away
              const paddle = controllables.current[i];
              let safe_x = pos.x;
              let safe_y = pos.y;

              // Additional safety check: ensure ball is above paddle
              if (safe_y + this.size > paddle.y - 5) {
                safe_y = paddle.y - this.size - 10;
              }

              // Ensure ball has upward velocity after paddle collision
              let safe_vx = pos.vx;
              let safe_vy = Math.min(pos.vy, -1); // Ensure upward movement

              return {
                x: safe_x,
                y: safe_y,
                vx: safe_vx,
                vy: safe_vy
              };
            }
          }

          // Check collisions with dingers
          for (let i = 0; i < dingers.length; i++) {
            const pos = dingers[i].check_collision_with_pos(check_x, check_y);
            if (pos) {
              console.log("Dinger collision detected:", i);
              dingers[i].justHit = true;

              // Calculate safe position by moving ball away from dinger center
              const dx = prev_x - dingers[i].x;
              const dy = prev_y - dingers[i].y;
              const distance = Math.sqrt(dx * dx + dy * dy);
              const safeDistance = this.size + dingers[i].size + 2;

              let safe_x, safe_y;
              if (distance > 0) {
                safe_x = dingers[i].x + (dx / distance) * safeDistance;
                safe_y = dingers[i].y + (dy / distance) * safeDistance;
              } else {
                // Fallback if ball is exactly on dinger center
                safe_x = prev_x;
                safe_y = prev_y;
              }

              return {
                x: safe_x,
                y: safe_y,
                vx: pos.vx,
                vy: pos.vy
              };
            }
          }

          // Check collisions with dinger manager dingers
          for (let i = 0; i < dingerMan.dingers.length; i++) {
            const pos = dingerMan.dingers[i].check_collision_with_pos(check_x, check_y);
            if (pos) {
              console.log("DingerMan collision detected:", i);
              dingerMan.dingers[i].justHit = true;

              // Calculate safe position by moving ball away from dinger center
              const dx = prev_x - dingerMan.dingers[i].x;
              const dy = prev_y - dingerMan.dingers[i].y;
              const distance = Math.sqrt(dx * dx + dy * dy);
              const safeDistance = this.size + dingerMan.dingers[i].size + 2;

              let safe_x, safe_y;
              if (distance > 0) {
                safe_x = dingerMan.dingers[i].x + (dx / distance) * safeDistance;
                safe_y = dingerMan.dingers[i].y + (dy / distance) * safeDistance;
              } else {
                // Fallback if ball is exactly on dinger center
                safe_x = prev_x;
                safe_y = prev_y;
              }

              return {
                x: safe_x,
                y: safe_y,
                vx: pos.vx,
                vy: pos.vy
              };
            }
          }

          // Update previous position for next iteration
          prev_x = check_x;
          prev_y = check_y;
        }

        return false;
      }

      startPaddleHitCooldown() {
        this.canBeHit = false;
        setTimeout(() => {
          this.canBeHit = true;
        }, 1000)
      }
    }

    const MAX_ROTATION = 0.5;
    const MAX_ROTATION_COUNT = 50;

    const MIN_UP_VELOCITY = -3;

    class ForceApplicator {
      constructor(x, y, width, height, left, pivot_x, pivot_y) {
        this.x = x;
        this.y = y;

        this.pivot_x = pivot_x + x;
        this.pivot_y = pivot_y + y;

        this.d_theta = 0; // rotation velocity

        this.width = width;
        this.height = height;
        this.rotate_left = left;

        this.rect_midpoints = getMiddleOfRectangle(this.x, this.y, this.width, this.height);
        this.rotate_offset = this.rotate_left ? this.width / 2.2 : -this.width / 2.2

        this.rotation = 0.0;
        this.rotation_count = 0;
        this.rotating = false;
      }

      update() {
        if (checkMouseInRadius(getMiddleOfRectangle(this.x, this.y, this.width, this.height)
          , mousePosRef.current, this.width) && (Math.abs(this.rotation) < 0.01) &&
          mouseClickRef.current) {
          this.rotating = true;
          this.rotation_count = 0;
        }
        if (this.rotating) {
          if (Math.abs(this.rotation) < MAX_ROTATION) {
            this.rotation += this.rotate_left ? -this.d_theta : this.d_theta;
            this.d_theta += 0.02;
          } else if (this.rotation_count > MAX_ROTATION_COUNT) {
            this.rotating = false;
            this.d_theta = 0.0;
          } else {
            this.rotation_count += 1;
          }
        } else {
          if (Math.abs(this.rotation) > 0.1) {
            this.rotation += this.rotate_left ? -this.d_theta : this.d_theta;
            this.d_theta -= 0.001;
          } else {
            this.d_theta = 0.0;
            this.rotation = 0.0;
          }
        }
        // this.check_ball_collision();
      }

      // transform the ball's coordinate system into the paddle's
      // check_ball_collision(val_x = null, val_y = null) {
      //   if (!ballRef.current.canBeHit) { return }

      //   let ball_pos;
      //   if (val_x && val_y) {
      //     ball_pos = { x: val_x, y: val_y }
      //   } else {
      //     ball_pos = { x: ballRef.current.x, y: ballRef.current.y }
      //   }

      //   const point_x = this.rect_midpoints.x - this.rotate_offset;
      //   const point_y = this.rect_midpoints.y;

      //   const dx = ball_pos.x - point_x;
      //   const dy = ball_pos.y - point_y;

      //   const new_x = point_x + dx * Math.cos(-this.rotation) - dy * Math.sin(-this.rotation);
      //   const new_y = point_y + dy * Math.cos(-this.rotation) + dx * Math.sin(-this.rotation);
      //   const ball_pos_transformed = { x: new_x, y: new_y };

      //   const rect_paddle = { left: this.x, right: this.x + this.width, top: this.y, bottom: this.y + this.height }
      //   // kinky
      //   const paddle_padded = padRect(rect_paddle, 2, 5);

      //   // check collision
      //   if (inRect(paddle_padded, ball_pos_transformed.x, ball_pos_transformed.y, ballRef.current.size)) {
      //     if (Math.abs(this.rotation) > 0.0) {
      //       const normalAngle = -Math.PI / 2 + this.rotation;
      //       const normalX = Math.cos(normalAngle);
      //       const normalY = Math.sin(normalAngle);

      //       const dotProduct = ballRef.current.vx * normalX + ballRef.current.vy * normalY;
      //       ballRef.current.vx -= 2 * dotProduct * normalX;
      //       ballRef.current.vy -= (2 * dotProduct * normalY);

      //       const speedMultiplier = 2.0;
      //       ballRef.current.vx *= speedMultiplier;
      //       ballRef.current.vy *= speedMultiplier;

      //       if (this.rotating && this.d_theta > 0) {
      //         const tangentialForce = this.d_theta * 15;
      //         ballRef.current.vx += this.rotate_left ? -tangentialForce : tangentialForce;
      //         ballRef.current.vy -= (tangentialForce);
      //       }
      //       // move ball outside paddle along the normal
      //       const separationDistance = ballRef.current.size + 5;
      //       ballRef.current.x += normalX * separationDistance;
      //       ballRef.current.y += normalY * separationDistance;
      //     } else {
      //       ballRef.current.vy = -ballRef.current.vy * 1.1;
      //       ballRef.current.y = this.y - ballRef.current.size - 3;
      //     }

      //     if (ballRef.current.vy < 0.0 && ballRef.current.vy > MIN_UP_VELOCITY) {
      //       ballRef.current.vy = MIN_UP_VELOCITY;
      //     }

      //     this.d_theta = 0.0;
      //     this.rotation_count = 0;
      //     this.rotating = false;

      //     ballRef.current.startPaddleHitCooldown();
      //   }
      // }

      check_collision_with_pos(x, y) {
        if (!ballRef.current) return false;

        const new_velocity = { vx: ballRef.current.vx, vy: ballRef.current.vy }
        const ball_pos = { x: x, y: y }

        const point_x = this.rect_midpoints.x - this.rotate_offset;
        const point_y = this.rect_midpoints.y;

        const dx = ball_pos.x - point_x;
        const dy = ball_pos.y - point_y;

        let new_x = point_x + dx * Math.cos(-this.rotation) - dy * Math.sin(-this.rotation);
        let new_y = point_y + dy * Math.cos(-this.rotation) + dx * Math.sin(-this.rotation);
        const ball_pos_transformed = { x: new_x, y: new_y };

        const rect_paddle = { left: this.x, right: this.x + this.width, top: this.y, bottom: this.y + this.height }
        const paddle_padded = padRect(rect_paddle, 2, 5);

        // check collision
        if (inRect(paddle_padded, ball_pos_transformed.x, ball_pos_transformed.y, ballRef.current.size)) {
          this.d_theta = 0.0;
          this.rotation_count = 0;
          this.rotating = false;

          if (Math.abs(this.rotation) > 0.0) {
            const normalAngle = -Math.PI / 2 + this.rotation;
            const normalX = Math.cos(normalAngle);
            const normalY = Math.sin(normalAngle);

            const dotProduct = new_velocity.vx * normalX + new_velocity.vy * normalY;
            new_velocity.vx -= 2 * dotProduct * normalX;
            new_velocity.vy -= (2 * dotProduct * normalY);

            const speedMultiplier = 2.0;
            new_velocity.vx *= speedMultiplier;
            new_velocity.vy *= speedMultiplier;

            if (Math.abs(this.d_theta) > 0) {
              const tangentialForce = this.d_theta * 15;
              new_velocity.vx += this.rotate_left ? -tangentialForce : tangentialForce;
              new_velocity.vy -= tangentialForce;
            }

            const separationDistance = ballRef.current.size + 15; // Increased separation

            new_x = ball_pos.x + normalX * separationDistance;
            new_y = ball_pos.y + normalY * separationDistance;

            if (new_y > this.y - ballRef.current.size - 10) {
              new_y = this.y - ballRef.current.size - 10;
            }

          } else {

            new_velocity.vy = -Math.abs(new_velocity.vy) * 1.1;
            new_y = this.y - ballRef.current.size - 10;
            new_x = ball_pos.x;
          }

          // Ensure minimum upward velocity
          if (new_velocity.vy < 0.0 && new_velocity.vy > MIN_UP_VELOCITY) {
            new_velocity.vy = MIN_UP_VELOCITY;
          }

          // if ball would still be inside paddle, push it further away
          const safety_check_rect = padRect(rect_paddle, ballRef.current.size + 5, ballRef.current.size + 5);
          if (inRect(safety_check_rect, new_x, new_y, ballRef.current.size)) {
            new_y = this.y - ballRef.current.size - 20;
            new_velocity.vy = Math.min(new_velocity.vy, -2); // Ensure upward movement
          }

          return { x: new_x, y: new_y, vx: new_velocity.vx, vy: new_velocity.vy }
        }
        return false;
      } draw() {
        ctx.save();

        ctx.beginPath();

        if (Math.abs(this.rotation) > 0.01) {
          ctx.translate(this.rect_midpoints.x - this.rotate_offset, this.rect_midpoints.y)
          ctx.rotate(this.rotation);
          ctx.translate(-(this.rect_midpoints.x - this.rotate_offset), -this.rect_midpoints.y)
        } else {
          this.rotation = 0.0;
        }
        ctx.fillStyle = theme.secondary;
        ctx.rect(this.x, this.y, this.width, this.height);


        ctx.fill();
        ctx.closePath();

        ctx.beginPath();
        ctx.arc(this.rect_midpoints.x - this.rotate_offset, this.rect_midpoints.y, 3, 0, Math.PI * 2);
        ctx.fillStyle = theme.primary;
        ctx.fill();
        ctx.closePath();


        ctx.restore();
      }
    }

    class Dingers {
      constructor(x, y, size) {
        this.x = x;
        this.y = y;
        this.size = size;
        this.starting_size = size;
        this.color = getRandomColour();
        this.shadow_size = 0;
        this.ticks = 0;
        this.justHit = false;
        this.canBeHit = true;
      }

      startHitCooldown() {
        this.canBeHit = false;
        setTimeout(() => {
          this.canBeHit = true;
        }, 100) // Reduced from 400 to 100ms to prevent missing collisions
      }

      update() {
        // const collision_result = this.check_ball_collision()
        // if (collision_result !== false) {
        //   this.shadow = 20;

        //   const dx = ballRef.current.x - collision_result.x;
        //   const dy = ballRef.current.y - collision_result.y;
        //   const angle2 = Math.atan2(dy, dx);

        //   ballRef.current.vx = (Math.cos(angle2) * bouncynessRef.current) / 100 + ballRef.current.vx;
        //   ballRef.current.vy = (Math.sin(angle2) * bouncynessRef.current) / 100 - ballRef.current.vy;

        //   this.justHit = true;
        // }

        if (this.justHit) {
          this.size += 3
          this.shadow = 20
          this.sizeTickStart = true;
          this.justHit = false;
          this.startHitCooldown();
        }

        if (this.size > this.starting_size) {
          this.size -= 0.01
        }

        if (this.shadow > 0) {
          this.shadow -= 0.01;
        }

      }

      check_collision_with_pos(x, y) {
        if (!this.canBeHit) { return false }
        let dx, dy;
        dx = (x - this.x) ** 2;
        dy = (y - this.y) ** 2;
        if (dx + dy < (this.size + ballRef.current.size) ** 2) {
          // Calculate collision normal (from dinger center to ball)
          const dx_norm = x - this.x;
          const dy_norm = y - this.y;
          const distance = Math.sqrt(dx_norm * dx_norm + dy_norm * dy_norm);

          if (distance > 0) {
            // Normalize the collision normal
            const nx = dx_norm / distance;
            const ny = dy_norm / distance;

            // Reflect velocity using the normal
            const dotProduct = ballRef.current.vx * nx + ballRef.current.vy * ny;
            const new_vx = ballRef.current.vx - 2 * dotProduct * nx;
            const new_vy = ballRef.current.vy - 2 * dotProduct * ny;

            // Add some bounciness
            const bounceMultiplier = (bouncynessRef.current) / 100;
            return {
              x: x,
              y: y,
              vx: new_vx * bounceMultiplier,
              vy: new_vy * bounceMultiplier
            };
          }
        }
        return false
      }

      draw() {
        ctx.save();
        ctx.beginPath();
        ctx.shadowBlur = this.shadow;
        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
        ctx.fillStyle = this.color;
        ctx.fill();
        ctx.closePath();
        ctx.restore();
      }
    }

    function initScene() {
      initDingers();
      ballRef.current = new Ball(Math.random() * canvas.width, Math.random() * 0.5 * canvas.height + 20, Math.random() * 2, Math.random() * 2);
      // ballRef.current = new Ball(605, 600, 0, );

      const paddle_width = canvas.width / 5;

      const left_paddle_x = canvas.width / 4;
      const right_paddle_x = 3 * canvas.width / 4 - paddle_width;
      const paddle_y = canvas.height * 5 / 6

      const left_paddle = new ForceApplicator(left_paddle_x, paddle_y, paddle_width, 20, true, 20, 10);
      const right_paddle = new ForceApplicator(right_paddle_x, paddle_y, paddle_width, 20, false, paddle_width - 20, 10);

      controllables.current.push(left_paddle);
      controllables.current.push(right_paddle);
    }

    class DingerManager {
      constructor() {
        this.childDingerPositions = [];
        this.dingers = [];
        this.change_existing_dingers_to_grid();
      }

      change_existing_dingers_to_grid() {
        const canvasWidth = canvasRef.current.width;
        const canvasHeight = canvasRef.current.height;
        const centerX = canvasWidth / 2;
        const centerY = canvasHeight / 2;
        const verticalOffset = canvasHeight / 6;

        const gridPositions = [];
        let offsetRow = false;

        for (let y = centerY - verticalOffset; y < centerY + canvasHeight / 8; y += gridSpacingY.current) {
          offsetRow = !offsetRow;

          if (!offsetRow) {
            gridPositions.push({ x: centerX, y });
          }

          for (let x = gridSpacingX.current; x < centerX; x += gridSpacingX.current) {
            const xOffset = offsetRow ? x + gridSpacingX.current / 2 : x;

            if (xOffset < centerX) {
              gridPositions.push({ x: centerX + xOffset, y });
              gridPositions.push({ x: centerX - xOffset, y });
            }
          }
        }

        while (this.dingers.length > gridPositions.length) {
          this.dingers.pop();
        }

        gridPositions.forEach((pos, index) => {
          if (index < this.dingers.length) {
            this.dingers[index].x = pos.x;
            this.dingers[index].y = pos.y;
          } else {
            this.dingers.push(new Dingers(pos.x, pos.y, 5));
          }
        });
      }

      update_and_draw() {
        this.change_existing_dingers_to_grid()
        this.dingers.forEach((dinger) => {
          dinger.update();
          dinger.draw();
        })
      }
    }

    let dingers = [];

    const dingerMan = new DingerManager()

    function initDingers() {
      // line of dingers at the bottom
      const dinger_y = canvas.height * 5 / 6;

      const dinger_size = canvas.width * 0.02;
      const dinger_spacing = canvas.width * 0.04;
      const dinger_y_spacing = canvas.width * 0.03

      for (let i = 0; i < 6; i++) {
        dingers.push(new Dingers(i * dinger_spacing + dinger_size, dinger_y + i * 16 - dinger_y_spacing, dinger_size))
      }

      for (let i = 0; i < 6; i++) {
        dingers.push(new Dingers(canvas.width - (i * dinger_spacing + dinger_size), dinger_y + i * 16 - dinger_y_spacing, dinger_size))
      }
    }


    function animate() {
      clearCanvas(ctx, canvas);

      if (ballRef.current) {
        ballRef.current.update()
        ballRef.current.draw()
      }

      controllables.current.forEach((controllable) => {
        controllable.update();
        controllable.draw();
      })

      dingers.forEach((dinger) => {
        dinger.update();
        dinger.draw();
      })

      dingerMan.update_and_draw();
    }

    initScene();

    return {
      frame: animate,
      cleanup: () => {
        controllables.current = [];
        ballRef.current = null;
      },
    };
  }, [theme.primary, theme.secondary]);

  useEffect(() => {
    visibleUIRef.current = visibleUI;
  }, [visibleUI]);

  return (
    <>
      <SceneCanvas ref={canvasRef} />
      {visibleUI && (
        <div style={{ zIndex: 3000 }}>
          <ChangerGroup
            valueArrays={[
              {
                title: "Simulation Speed:",
                valueRef: simulationSpeedRef,
                minValue: "1",
                maxValue: "200.0",
                type: CHANGER_TYPE.SLIDER,
              },
              {
                title: "Grid Spacing X:",
                valueRef: gridSpacingX,
                minValue: "100",
                maxValue: "400",
                type: CHANGER_TYPE.SLIDER,
              },
              {
                title: "Grid Spacing Y:",
                valueRef: gridSpacingY,
                minValue: "100",
                maxValue: "400",
                type: CHANGER_TYPE.SLIDER,
              },
              {
                title: "Ball Bounce Factor:",
                valueRef: bouncynessRef,
                minValue: "100",
                maxValue: "300",
                type: CHANGER_TYPE.SLIDER,
              },
            ]}
            rerenderSetter={setRender}
          />

          <IconGroup icons={[
            { type: "MOUSE", text: "Click next to the levers to activate!" },
          ]} />
        </div>
      )}
    </>
  );
}
