import {
  useEffect,
  useState,
  createElement,
  useRef,
  useContext,
  useCallback,
  lazy,
  Suspense,
} from "react";
import { useTheme } from "../../../themes/ThemeProvider";
import { MobileContext } from "../../../contexts/MobileContext";

import {
  faGithub,
  faLinkedin,
  faYoutube,
} from "@fortawesome/free-brands-svg-icons";
import { faBookOpen, faFolder } from "@fortawesome/free-solid-svg-icons";

import Snow from "./scenes/snow";
import Rain from "./scenes/rain";
import Stars from "./scenes/stars";
import Boids from "./scenes/boids";

import IconHover from "./iconHover";
import IconButton from "./IconButton";
import InlineCarousel from "./InlineCarousel";
import Conway from "./scenes/conway";
import WindTunnel from "./scenes/windtunnel";
import Hexapod from "./scenes/hexapod";
import Mandelbrot from "./scenes/mandelbrot";
import Plants from "./scenes/plants";
import Fire from "./scenes/fire";
import Fireworks from "./scenes/firework";
import Plinko from "./scenes/plinko";
import GravitalOrbs from "./scenes/gravitalorbs";
import Liquid from "./scenes/liquid";
import Life from "./scenes/life";
import Raven from "./scenes/raven";
import Clocks from "./scenes/clocks";
import { portfolioImages } from "./portfolio";
import Pinball from "./scenes/pinball";
import BallPit from "./scenes/ballpit";
import PID from "./scenes/pid";
import BadApple from "./scenes/badapple";
import SquishBall from "./scenes/squishball";
import Penguin from "./scenes/penguin";
import Runes from "./scenes/runes";
import Leaves from "./scenes/leaves";
import Backrooms from "./scenes/backrooms";
import BZ from "./scenes/bz";
import Hyperspace from "./scenes/hyperspace";

// Split out: react-markdown is a large dependency and the panel sits behind a
// click, so it is only fetched once the blog is opened for the first time.
const InlineBlog = lazy(() => import("./InlineBlog"));

const Scenes = {
  0: { component: Snow, name: "snow" },
  1: { component: Rain, name: "rain" },
  2: { component: Plants, name: "plants" },
  3: { component: Stars, name: "stars" },
  4: { component: Boids, name: "boids" },
  5: { component: Conway, name: "conway" },
  6: { component: Hexapod, name: "hexapod" },
  7: { component: Mandelbrot, name: "mandelbrot" },
  8: { component: Fire, name: "fire" },
  9: { component: Fireworks, name: "fireworks" },
  10: { component: Plinko, name: "plinko" },
  11: { component: GravitalOrbs, name: "gravitalorbs" },
  12: { component: Liquid, name: "liquid" },
  13: { component: Life, name: "life" },
  14: { component: Raven, name: "raven" },
  15: { component: Clocks, name: "clocks" },
  16: { component: Pinball, name: "pinball" },
  17: { component: BallPit, name: "ballpit" },
  18: { component: PID, name: "pid" },
  19: { component: BadApple, name: "badapple" },
  20: { component: SquishBall, name: "squishball" },
  21: { component: Penguin, name: "penguin" },
  22: { component: Runes, name: "runes" },
  23: { component: Leaves, name: "leaves" },
  24: { component: Backrooms, name: "backrooms" },
  25: { component: BZ, name: "bz" },
  26: { component: Hyperspace, name: "hyperspace" },
  27: { component: WindTunnel, name: "windtunnel" },
};

export default function Title({
  text = "Nicholas Teague",
  initialScene = "",
  proj = false,
  blog = false,
  initialPost = null,
  disableInitialShake = false,
  visibleUI = true,
  setVisibleUI = () => { },
  handleThemeToggle = () => { },
  handleVisibleToggle = () => { },
  onIntroComplete = () => { },
}) {
  const { theme } = useTheme();
  const mobile = useContext(MobileContext);
  const [isHover, setIsHover] = useState(false);
  const [currentScene, setCurrentScene] = useState(
    Math.floor(Math.random() * Object.keys(Scenes).length)
  );
  const leftShake = useRef(false);

  const [clicked, setClicked] = useState(false);
  const [autoShake, setAutoShake] = useState(disableInitialShake);
  const headerRef = useRef(null);
  const animationNameRef = useRef("");
  const [showCarousel, setShowCarousel] = useState(proj ?? false);
  const [showBlog, setShowBlog] = useState((blog ?? false) || initialPost !== null);
  // Latches on first open and stays mounted, so the close animation can play.
  const [blogMounted, setBlogMounted] = useState((blog ?? false) || initialPost !== null);

  const [displayedText, setDisplayedText] = useState("");
  const [typingDone, setTypingDone] = useState(false);
  const [sceneLabel, setSceneLabel] = useState("click the title to change scene");
  const [sceneLabelFaded, setSceneLabelFaded] = useState(false);
  const [iconsVisible, setIconsVisible] = useState(false);
  const [sceneLabelVisible, setSceneLabelVisible] = useState(false);
  const [settledUI, setSettledUI] = useState(false);
  const typingTime = 1000

  useEffect(() => {
    const fullText =
      text === "" || text === undefined
        ? "NTeague"
        : decodeURIComponent(text).replace(/%0A/g, "\n");

    let i = 0;
    setDisplayedText("");
    setTypingDone(false);
    setSceneLabel("click the title to change scene");
    setSceneLabelFaded(false);
    setIconsVisible(false);
    setSceneLabelVisible(false);
    setSettledUI(false);

    const interval = setInterval(() => {
      i++;
      setDisplayedText(fullText.slice(0, i));
      if (i >= fullText.length) {
        clearInterval(interval);
        setTypingDone(true);
        // 1. Scene label fades in
        setSceneLabelVisible(true);
        setTimeout(() => {
          // 2. Icons expand in
          setIconsVisible(true);
          setTimeout(() => {
            // 3. Side buttons + value changers appear
            setSettledUI(true);
            onIntroComplete();
          }, 1000);
        }, 1000);
        // Scene label swaps to scene name after a pause
        setTimeout(() => {
          setSceneLabelFaded(true);
          setTimeout(() => {
            setSceneLabel(null);
            setTimeout(() => {
              setSceneLabelFaded(false);
            }, 100);
          }, 1000);
        }, 3000);
      }
    }, Math.round(1000 / fullText.length));

    return () => clearInterval(interval);
  }, [text]);

  const indexToSceneName = (index) => {
    return Scenes[index].name;
  }

  const sceneNameToIndex = (text) => {
    let index = undefined;
    const range = [...Array(Object.keys(Scenes).length).keys()];
    range.forEach(sceneIndex => {
      if (text === indexToSceneName(sceneIndex)) {
        index = sceneIndex;
      }
    });
    return index;
  }

  useEffect(() => {
    setShowCarousel(proj);
  }, [proj])

  useEffect(() => {
    const open = blog || initialPost !== null;
    setShowBlog(open);
    if (open) setBlogMounted(true);
  }, [blog, initialPost])

  // Only one inline panel at a time, so the column never stacks two cards.
  const toggleCarousel = useCallback(() => {
    setShowCarousel((prev) => {
      if (!prev) setShowBlog(false);
      return !prev;
    });
  }, []);

  const toggleBlog = useCallback(() => {
    setBlogMounted(true);
    setShowBlog((prev) => {
      if (!prev) setShowCarousel(false);
      return !prev;
    });
  }, []);

  useEffect(() => {
    setAutoShake(disableInitialShake);
  }, [disableInitialShake])

  useEffect(() => {
    if (initialScene === "") {
      setCurrentScene(Math.floor(Math.random() * Object.keys(Scenes).length));
    } else {
      const normalizedScene = decodeURIComponent(
        initialScene.trim().toLowerCase()
      );
      const sceneIndex = sceneNameToIndex(normalizedScene);
      if (sceneIndex !== undefined) {
        setCurrentScene(sceneIndex);
      } else {
        console.warn(
          `Invalid initialScene: "${initialScene}". Falling back to a random scene.`
        );
        setCurrentScene(Math.floor(Math.random() * Object.keys(Scenes).length));
      }
    }
  }, [initialScene]);

  const intervalRef = useRef(null);

  const triggerShake = useCallback(() => {
    const name = getShakeTransform(leftShake.current);
    animationNameRef.current = name;
    setClicked(true);
  }, []);

  useEffect(() => {
    if (autoShake && settledUI) {
      intervalRef.current = setInterval(() => {
        triggerShake();
      }, 500);
    }
    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current);
      setIsHover(false);
    };
  }, [autoShake, settledUI, triggerShake]);

  useEffect(() => {
    if (clicked) {
      setTimeout(() => {
        setClicked(false);
      }, 500);
    }
  }, [clicked]);

  const renderScene = () => {
    return Scenes[currentScene].component;
  };

  const getShakeTransform = (left) => {
    const animationName = `cartoony-shake-${Math.random()
      .toString(36)
      .substr(2, 5)}`; // Unique animation name

    let keyframes;
    if (left) {
      keyframes = `
      @keyframes ${animationName} {
        0% { transform: translate(0, 0) rotate(0deg); }
        25% { transform: translate(-10px, -5px) rotate(-5deg); }
        50% { transform: translate(12px, 6px) rotate(4deg); }
        75% { transform: translate(-8px, 4px) rotate(-3deg); }
        100% { transform: translate(0, 0) rotate(0deg); }
      }
    `;
    } else {
      keyframes = `
      @keyframes ${animationName} {
        0% { transform: translate(0, 0) rotate(0deg); }
        25% { transform: translate(10px, 5px) rotate(5deg); }
        50% { transform: translate(-12px, -6px) rotate(-4deg); }
        75% { transform: translate(8px, -4px) rotate(3deg); }
        100% { transform: translate(0, 0) rotate(0deg); }
      }
    `;
    }

    // Inject the keyframes into a style tag
    const styleSheet = document.styleSheets[0];
    styleSheet.insertRule(keyframes, styleSheet.cssRules.length);

    return animationName; // Return the animation name
  };

  const getSceneName = (index) => {
    return (
      indexToSceneName(index) ||
      "Unknown"
    );
  };

  const handleLeftClickTitle = useCallback((event, overrideEvent = false) => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
      setAutoShake(false);
    }
    if (event.button === 0 || overrideEvent) {
      leftShake.current = true;
      triggerShake();
      setCurrentScene((currentScene + 1) % Object.keys(Scenes).length);
    }
  }, [currentScene, triggerShake]);

  const handleRightClickTitle = useCallback((event) => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
      setAutoShake(false);
    }
    if (event) event.preventDefault();
    leftShake.current = false;
    triggerShake();
    setCurrentScene(
      currentScene - 1 < 0 ? Object.keys(Scenes).length - 1 : currentScene - 1
    );
  }, [currentScene, triggerShake]);

  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.key === "ArrowLeft" || e.key === "a") {
        if (visibleUI) {
          setIsHover(true);
          setTimeout(() => {
            setIsHover(false);
          }, 500);
        }
        handleRightClickTitle();
      } else if (e.key === "ArrowRight" || e.key === "d") {
        if (visibleUI) {
          setIsHover(true);
          setTimeout(() => {
            setIsHover(false);
          }, 500);
        }

        handleLeftClickTitle({ button: 0 }, true);
      } else if (e.key === "v") {
        handleVisibleToggle();
      } else if (e.key === "c") {
        handleThemeToggle();
      }
    };

    window.addEventListener("keydown", handleKeyDown);

    return () => {
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, [handleLeftClickTitle, handleRightClickTitle, handleThemeToggle, handleVisibleToggle, visibleUI]);

  return (
    <>
      <div
        style={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          height: "var(--app-height)",
          flexDirection: "column",
          position: "relative",
          backgroundColor: theme.primary,
          color: theme.accent,
          fontFamily: theme.font,
          overflow: "hidden"
        }}
      >
        {createElement(renderScene(visibleUI), { visibleUI: visibleUI && settledUI })}
        {visibleUI && (
          <header
            ref={headerRef}
            onMouseEnter={() => setIsHover(true)}
            onMouseLeave={() => setIsHover(false)}
            onMouseDown={handleLeftClickTitle}
            onContextMenu={handleRightClickTitle}
            style={{
              // Mobile scales with the viewport instead of sitting at a fixed
              // 2.2em, so the title keeps its weight against the icon row on
              // larger phones without overflowing small ones.
              fontSize: mobile ? "clamp(2.2rem, 9vw, 3.6rem)" : "5em",
              textAlign: "center",
              color: isHover ? theme.secondary : theme.accent,
              fontWeight: "bold",
              zIndex: 10,
              transition: "color 0.8s ease, transform 1.5s ease",
              position: "relative",
              cursor: "pointer",
              WebkitUserSelect: "none",
              WebkitTouchCallout: "none",
              KhtmlUserSelect: "none",
              MozUserSelect: "none",
              userSelect: "none",
              msUserSelect: "none",
              animation:
                clicked && animationNameRef.current
                  ? `${animationNameRef.current} 0.5s ease`
                  : "none",
              whiteSpace: "pre-wrap",
            }}
            id="title"
            aria-label="Next scene (left click), previous scene (right click)"
            title="Next scene (left click), previous scene (right click)"
          >
            {displayedText}
            {!typingDone && (
              <span
                style={{
                  borderRight: `0.08em solid ${isHover ? theme.secondary : theme.accent}`,
                  animation: "blink 0.7s step-end infinite",
                  marginLeft: "2px",
                }}
              />
            )}
          </header>
        )}
        {/* Mobile: show menu button, else show scene and links inline */}
        {visibleUI && <InlineCarousel
          images={portfolioImages}
          isVisible={showCarousel}
          onClose={() => setShowCarousel(false)}
        />}
        {visibleUI && blogMounted && (
          <Suspense fallback={null}>
            <InlineBlog
              isVisible={showBlog}
              initialSlug={initialPost}
              onClose={() => setShowBlog(false)}
            />
          </Suspense>
        )}
        {visibleUI && (
          <>
            {!mobile && <div
              style={{
                display: "flex",
                justifyContent: "center",
                fontWeight: "bold",
                fontSize: "1.5em",
                WebkitUserSelect: "none",
                WebkitTouchCallout: "none",
                KhtmlUserSelect: "none",
                MozUserSelect: "none",
                userSelect: "none",
                msUserSelect: "none",
                zIndex: 100,
                paddingBottom: "0.5em",
                opacity: sceneLabelVisible && !sceneLabelFaded ? 1 : 0,
                transition: "opacity 1.0s ease",
              }}
              id="sceneLabel"
            >
              {sceneLabel === null ? `Current scene: ${getSceneName(currentScene)}` : sceneLabel}
            </div>}

            <div
              id="linkIcons"
              style={{
                display: "flex",
                justifyContent: "center",
                gap: iconsVisible ? (mobile ? "0.75em" : "1em") : "0em",
                // Smaller glyphs on mobile; IconButton/IconHover keep a 44px
                // tap target underneath them.
                fontSize: mobile ? "2em" : "3em",
                zIndex: 100,
                overflow: "hidden",
                maxWidth: iconsVisible ? "500px" : "0px",
                opacity: iconsVisible ? 1 : 0,
                transition: "max-width 0.5s cubic-bezier(0.4, 0, 0.2, 1), opacity 0.5s ease, gap 0.5s ease",
                // paddingBottom: "1em",
              }}
            >
              <IconButton
                icon={faFolder}
                onClick={toggleCarousel}
                openNewTab={false}
                title="View projects"
                style={{
                  transform: showCarousel ? 'scale(1.1)' : 'scale(1)',
                  transition: 'transform 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
                }}
              />
              <IconButton
                icon={faBookOpen}
                onClick={toggleBlog}
                openNewTab={false}
                title="Read the blog"
                style={{
                  transform: showBlog ? 'scale(1.1)' : 'scale(1)',
                  transition: 'transform 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
                }}
              />
              <IconHover
                icon={faGithub}
                link="https://www.github.com/coding-beagle"
              />
              <IconHover
                icon={faLinkedin}
                link="https://www.linkedin.com/in/nicholasp-teague/"
              />
              <IconHover
                icon={faYoutube}
                link="https://www.youtube.com/@ntprod"
              />
            </div>
          </>
        )}
      </div>
      <style>{`
        @keyframes blink {
          0%, 100% { border-color: transparent; }
          50% { border-color: inherit; }
        }
      `}</style>
    </>
  );
}
